import 'dart:convert';

Future<List<Object?>> loadCatalog(Future<String> Function() fetch) async {
  final body = await fetch(); // I/O wait: frames keep coming
  // Still the main isolate: no frame until the decode returns
  return jsonDecode(body) as List<Object?>;
}

import 'dart:convert';
import 'dart:isolate';

Future<List<Object?>> loadCatalog(Future<String> Function() fetch) async {
  final body = await fetch(); // I/O wait: frames keep coming
  // The decode runs on a worker isolate; the main one stays free
  return Isolate.run(() => jsonDecode(body) as List<Object?>);
}
